package ru.pulsedoma.issues;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import ru.pulsedoma.common.BusinessException;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.Instant;
import java.util.*;
import static ru.pulsedoma.issues.ExchangeTypes.*;

/** Explicit, versioned disclosure. An invitation grants access to a packet, never to a house or case. */
@Service
public class CaseExchangeService {
    private final JdbcTemplate db;
    private final ResidentCaseService cases;
    private final CaseWorkAccess access;
    private final AttachmentStore store;
    private final ObjectMapper mapper;
    private final CaseBotNotifications notifications;
    public CaseExchangeService(JdbcTemplate db,ResidentCaseService cases,CaseWorkAccess access,AttachmentStore store,ObjectMapper mapper,CaseBotNotifications notifications){this.db=db;this.cases=cases;this.access=access;this.store=store;this.mapper=mapper;this.notifications=notifications;}
    static String id(){return UUID.randomUUID().toString();}
    static String now(){return Instant.now().toString();}
    static String s(Map<String,Object> r,String k){return Objects.toString(r.get(k),null);}
    static int rev(Map<String,Object> r){return ((Number)r.get("revision")).intValue();}
    static BusinessException invalid(String text){return new BusinessException("INVALID_CASE",text);}
    static BusinessException missing(){return new BusinessException("CASE_NOT_FOUND","Материалы недоступны");}
    static BusinessException conflict(){return new BusinessException("CASE_CONFLICT","Данные изменились. Обновите страницу");}
    String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    static String hash(byte[] value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}catch(Exception e){throw new IllegalStateException(e);}}
    Map<String,Object> row(String table,String key){var rows=db.queryForList("SELECT * FROM "+table+" WHERE id=?",key);if(rows.isEmpty())throw missing();return rows.get(0);}
    String organization(String house){return db.queryForObject("SELECT organization_id FROM organization_houses WHERE house_id=? AND status='ACTIVE' ORDER BY organization_id LIMIT 1",String.class,house);}
    private void manager(String house,String user){if(!access.manager(house,user))throw missing();}
    private boolean sender(ResidentCaseService.CaseView c,String user){return !c.isAuthor()&&c.fullAccess()&&(c.kind()==CaseKind.PAYMENT?access.billing(c.houseId(),user):access.coordinator(c.id(),c.houseId(),user));}
    private ResidentCaseService.CaseView staff(String caseId,String user,Integer revision){var c=cases.get(caseId,user);if(!sender(c,user))throw missing();if(c.status()==CaseStatus.CLOSED)throw invalid("Сначала запросите повторное рассмотрение");if(revision!=null&&c.revision()!=revision)throw conflict();return c;}
    private void current(Map<String,Object> p){if(!access.exists("SELECT count(*) FROM resident_cases c JOIN organization_houses h ON h.house_id=c.house_id WHERE c.id=? AND h.organization_id=? AND h.status='ACTIVE'",p.get("case_id"),p.get("source_organization_id")))throw missing();}
    private Map<String,Object> mutate(String packet,String user,int revision,int caseRevision){var p=row("exchange_packets",packet);staff(s(p,"case_id"),user,caseRevision);current(p);if(rev(p)!=revision)throw conflict();return p;}
    private void state(Map<String,Object> p,PacketState... allowed){if(Arrays.stream(allowed).noneMatch(v->v.name().equals(s(p,"state"))))throw invalid("Действие недоступно на текущем шаге");}
    private void evidence(String version,String caseId){if(version==null||version.isBlank()||!access.exists("SELECT count(*) FROM case_document_versions v JOIN case_documents d ON d.id=v.document_id WHERE v.id=? AND d.case_id=?",version,caseId))throw invalid("Нужен подтверждающий документ из этого обращения");}
    private void history(String packet,Action action,String note,String evidence,String user,Object snapshot){db.update("INSERT INTO exchange_history(id,packet_id,action,note,evidence_version_id,actor_id,snapshot_json,created_at) VALUES (?,?,?,?,?,?,?,?)",id(),packet,action.name(),note,evidence,user,json(snapshot),now());}
    private void bump(Map<String,Object> p,Action action,String note,String proof,String user,String residentText){if(db.update("UPDATE exchange_packets SET revision=revision+1,updated_at=? WHERE id=? AND revision=?",now(),p.get("id"),rev(p))!=1)throw conflict();history(s(p,"id"),action,note,proof,user,row("exchange_packets",s(p,"id")));event(s(p,"case_id"),s(p,"id"),user,residentText);}
    private void event(String caseId,String packet,String user,String text){String next=null;if(text!=null)next=switch(PacketState.valueOf(s(row("exchange_packets",packet),"state"))){case SENT->"Ожидаем подтверждение получения материалов организацией";case RECEIVED->"Ожидаем ответ организации. Сотрудник контролирует срок";case ANSWERED->"Сотрудник проверяет полученный ответ организации";case REVIEWED->"Ответ организации рассмотрен. Сотрудник готовит следующий шаг";case CANCELLED->"Сотрудник уточняет следующий шаг после отмены передачи";default->null;};db.update("UPDATE resident_cases SET revision=revision+1,updated_at=?,next_step=CASE WHEN status='WAITING_RESIDENT' THEN next_step ELSE coalesce(?,next_step) END,status=CASE WHEN ? IS NOT NULL AND status NOT IN ('WAITING_RESIDENT','CLOSED') THEN 'IN_PROGRESS' ELSE status END WHERE id=?",now(),next,next,caseId);if(text!=null){db.update("INSERT INTO case_events(id,case_id,actor_id,type,text,created_at) VALUES (?,?,?,'UPDATED',?,?)",id(),caseId,user,text,now());notifications.enqueue(caseId,user,CaseEventType.UPDATED);}}
    public List<Map<String,Object>> channels(String house,String user){if(!access.manager(house,user)&&!access.dispatcher(house,user)&&!access.staffFunction(house,user,CaseFunction.COORDINATOR)&&!access.billing(house,user))throw missing();return db.queryForList("SELECT e.* FROM exchange_channels e JOIN organization_houses h ON h.house_id=e.house_id AND h.organization_id=e.source_organization_id WHERE e.house_id=? AND h.status='ACTIVE' ORDER BY e.created_at",house);}
    @Transactional public List<Map<String,Object>> channel(String house,String channel,ExchangeRequests.Channel r,String user){manager(house,user);String org=db.queryForObject("SELECT organization_id FROM uk_admin_houses WHERE house_id=? AND user_id=? AND access_status='ACTIVE' LIMIT 1",String.class,house,user);String key=channel==null?id():channel;
        if(channel==null){if(r.revision()!=0)throw conflict();db.update("INSERT INTO exchange_channels(id,house_id,source_organization_id,organization_name,participant_type,mode,contact,source_reference,disclosure_scope,state,checked_by,checked_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",key,house,org,r.organizationName(),r.participantType().name(),r.mode().name(),r.contact(),r.sourceReference(),r.disclosureScope(),r.state().name(),user,now(),now());}
        else{var old=row("exchange_channels",key);if(!house.equals(s(old,"house_id"))||!org.equals(s(old,"source_organization_id")))throw missing();if(db.update("UPDATE exchange_channels SET organization_name=?,participant_type=?,mode=?,contact=?,source_reference=?,disclosure_scope=?,state=?,checked_by=?,checked_at=?,revision=revision+1 WHERE id=? AND revision=?",r.organizationName(),r.participantType().name(),r.mode().name(),r.contact(),r.sourceReference(),r.disclosureScope(),r.state().name(),user,now(),key,r.revision())!=1)throw conflict();}
        db.update("INSERT INTO control_history(id,house_id,action,note,snapshot_json,actor_id,created_at) VALUES (?,?,'CHANNEL_SAVED',?,?,?,?)",id(),house,r.reason(),json(row("exchange_channels",key)),user,now());return channels(house,user);}
    public record Workspace(int revision,boolean canWork,List<Map<String,Object>> packets){}
    public Workspace workspace(String caseId,String user){var c=cases.get(caseId,user);if(!c.fullAccess())throw missing();boolean work=sender(c,user);var packets=new ArrayList<Map<String,Object>>();for(var p:db.queryForList("SELECT * FROM exchange_packets WHERE case_id=? ORDER BY rowid DESC",caseId)){
            if(!work){if(List.of("DRAFT","READY","CANCELLED").contains(s(p,"state")))continue;var safe=new LinkedHashMap<String,Object>();for(String k:List.of("id","state","due_at","due_basis"))safe.put(k,p.get(k));safe.put("answers",db.queryForList("SELECT resident_summary,reviewed_at FROM exchange_replies WHERE packet_id=? AND state='ACCEPTED' ORDER BY version",p.get("id")));packets.add(safe);}
            else{p.put("files",db.queryForList("SELECT id,version_id,title,mime,sha256,size_bytes FROM exchange_packet_files WHERE packet_id=?",p.get("id")));var replies=db.queryForList("SELECT * FROM exchange_replies WHERE packet_id=? AND state<>'DRAFT' ORDER BY version",p.get("id"));for(var a:replies)a.put("files",db.queryForList("SELECT id,title,mime,sha256,size_bytes,imported_version_id FROM exchange_reply_files WHERE reply_id=?",a.get("id")));p.put("answers",replies);p.put("history",db.queryForList("SELECT action,note,evidence_version_id,created_at FROM exchange_history WHERE packet_id=? ORDER BY rowid",p.get("id")));p.put("invitations",db.queryForList("SELECT id,recipient_name,participation_basis,expires_at,accepted_by,revoked_at FROM exchange_invitations WHERE packet_id=?",p.get("id")));packets.add(p);}}
        return new Workspace(c.revision(),work&&c.status()!=CaseStatus.CLOSED,packets);}
    @Transactional public Workspace draft(String caseId,String packet,ExchangeRequests.Packet r,String user){var c=staff(caseId,user,r.caseRevision());var channel=row("exchange_channels",r.channelId());if(!c.houseId().equals(s(channel,"house_id")))throw missing();if(!access.exists("SELECT count(*) FROM organization_houses WHERE house_id=? AND organization_id=? AND status='ACTIVE'",c.houseId(),channel.get("source_organization_id")))throw missing();String key=packet==null?id():packet;
        if(new HashSet<>(r.versionIds()).size()!=r.versionIds().size())throw invalid("В списке повторяются документы");for(String v:r.versionIds())evidence(v,caseId);
        if(packet==null){if(r.revision()!=0)throw conflict();db.update("INSERT INTO exchange_packets(id,case_id,channel_id,source_organization_id,subject,statement,disclosure_basis,authority,materials_note,include_address,state,due_at,due_basis,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,'DRAFT',?,?,?,?,?)",key,caseId,r.channelId(),channel.get("source_organization_id"),r.subject(),r.statement(),r.disclosureBasis(),r.authority(),r.materialsNote(),r.includeAddress()?1:0,r.dueAt(),r.dueBasis(),user,now(),now());}
        else{var old=mutate(key,user,r.revision(),r.caseRevision());if(!caseId.equals(s(old,"case_id")))throw missing();state(old,PacketState.DRAFT);db.update("UPDATE exchange_packets SET channel_id=?,source_organization_id=?,subject=?,statement=?,disclosure_basis=?,authority=?,materials_note=?,include_address=?,due_at=?,due_basis=? WHERE id=?",r.channelId(),channel.get("source_organization_id"),r.subject(),r.statement(),r.disclosureBasis(),r.authority(),r.materialsNote(),r.includeAddress()?1:0,r.dueAt(),r.dueBasis(),key);db.update("DELETE FROM exchange_packet_files WHERE packet_id=?",key);}
        for(String v:r.versionIds())db.update("INSERT INTO exchange_packet_files(id,packet_id,version_id,title,mime,sha256,size_bytes,storage_key) SELECT ?,?,v.id,d.title,v.mime,v.sha256,v.size_bytes,v.storage_key FROM case_document_versions v JOIN case_documents d ON d.id=v.document_id WHERE v.id=?",id(),key,v);
        bump(row("exchange_packets",key),Action.PACKET_DRAFTED,r.reason(),null,user,null);return workspace(caseId,user);}
    @Transactional public Workspace decision(String key,String action,ExchangeRequests.Decision r,String user){var p=mutate(key,user,r.revision(),r.caseRevision());String caseId=s(p,"case_id"),proof=null;Action audit;String text;
        switch(action){case "seal"->{state(p,PacketState.DRAFT);var channel=row("exchange_channels",s(p,"channel_id"));if(!"VERIFIED".equals(s(channel,"state")))throw invalid("УК должна проверить канал получателя");db.update("UPDATE exchange_packets SET state='READY',channel_snapshot=?,address_snapshot=CASE WHEN include_address=1 THEN (SELECT address FROM houses WHERE id=(SELECT house_id FROM resident_cases WHERE id=?)) ELSE NULL END WHERE id=?",json(channel),caseId,key);audit=Action.PACKET_SEALED;text=null;}
            case "send"->{state(p,PacketState.READY);proof=r.evidenceVersionId();evidence(proof,caseId);db.update("UPDATE exchange_packets SET state='SENT' WHERE id=?",key);audit=Action.PACKET_SENT;text="Сотрудник зафиксировал передачу материалов организации. Ожидаем подтверждение получения.";}
            case "receive"->{state(p,PacketState.SENT);manual(p);proof=r.evidenceVersionId();evidence(proof,caseId);unusedProof(key,proof);db.update("UPDATE exchange_packets SET state='RECEIVED' WHERE id=?",key);audit=Action.PACKET_RECEIVED;text="Получение материалов подтверждено документом. Ожидаем ответ организации.";}
            case "cancel"->{state(p,PacketState.DRAFT,PacketState.READY,PacketState.SENT,PacketState.RECEIVED,PacketState.ANSWERED);db.update("UPDATE exchange_packets SET state='CANCELLED' WHERE id=?",key);audit=Action.PACKET_CANCELLED;text="Передача материалов отменена. Сотрудник продолжает сопровождение обращения.";}
            default->throw invalid("Неизвестное действие");}
        bump(p,audit,r.note(),proof,user,text);return workspace(caseId,user);}
    private void unusedProof(String packet,String proof){if(access.exists("SELECT count(*) FROM exchange_history WHERE packet_id=? AND evidence_version_id=?",packet,proof))throw invalid("Прежний документ не подтверждает новый шаг. Приложите отдельное подтверждение или новую версию");}
    private void manual(Map<String,Object> p){try{if(!"MANUAL".equals(mapper.readTree(s(p,"channel_snapshot")).path("mode").asText()))throw invalid("Получение и ответ подтверждает участник в своём кабинете");}catch(java.io.IOException e){throw new IllegalStateException(e);}}
    private void portal(Map<String,Object> p){try{if(!"PORTAL".equals(mapper.readTree(s(p,"channel_snapshot")).path("mode").asText()))throw invalid("Для этого канала выбран ручной обмен с документами");}catch(java.io.IOException e){throw new IllegalStateException(e);}}
    @Transactional public Workspace schedule(String key,ExchangeRequests.Schedule r,String user){var p=mutate(key,user,r.revision(),r.caseRevision());state(p,PacketState.READY,PacketState.SENT,PacketState.RECEIVED,PacketState.ANSWERED);db.update("UPDATE exchange_packets SET due_at=?,due_basis=? WHERE id=?",r.dueAt(),r.dueBasis(),key);bump(p,Action.DEADLINE_CHANGED,r.reason(),null,user,"Срок ответа организации уточнён: "+r.dueBasis());return workspace(s(p,"case_id"),user);}
    public record Issued(String token,String id,String expiresAt){}
    @Transactional public Issued invite(String key,ExchangeRequests.Invite r,String user){var p=mutate(key,user,r.revision(),r.caseRevision());state(p,PacketState.SENT,PacketState.RECEIVED);portal(p);byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token="xp_"+Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),keyId=id(),expires=Instant.now().plusSeconds(r.days()*86400L).toString();db.update("INSERT INTO exchange_invitations(id,packet_id,token_hash,recipient_name,participation_basis,expires_at,created_by,created_at) VALUES (?,?,?,?,?,?,?,?)",keyId,key,hash(token.getBytes(StandardCharsets.UTF_8)),r.recipientName(),r.participationBasis(),expires,user,now());bump(p,Action.INVITATION_CREATED,"Подготовлен доступ: "+r.recipientName(),null,user,null);return new Issued(token,keyId,expires);}
    @Transactional public Workspace revoke(String invitation,ExchangeRequests.Decision r,String user){var i=row("exchange_invitations",invitation);var p=row("exchange_packets",s(i,"packet_id"));var c=cases.get(s(p,"case_id"),user);if(!sender(c,user))throw missing();current(p);if(rev(p)!=r.revision()||c.revision()!=r.caseRevision())throw conflict();db.update("UPDATE exchange_invitations SET revoked_at=? WHERE id=?",now(),invitation);bump(p,Action.INVITATION_REVOKED,r.note(),null,user,null);return workspace(s(p,"case_id"),user);}
    @Transactional public Map<String,Object> accept(String token,String user){var list=db.queryForList("SELECT * FROM exchange_invitations WHERE token_hash=?",hash(token.getBytes(StandardCharsets.UTF_8)));if(list.isEmpty())throw missing();var i=list.get(0);var p=row("exchange_packets",s(i,"packet_id"));current(p);state(p,PacketState.SENT,PacketState.RECEIVED);if(i.get("revoked_at")!=null||!Instant.parse(s(i,"expires_at")).isAfter(Instant.now())||!access.exists("SELECT count(*) FROM users WHERE id=? AND status='ACTIVE'",user))throw missing();
        if(user.equals(s(i,"created_by"))||user.equals(s(p,"created_by"))||access.exists("SELECT count(*) FROM resident_cases WHERE id=? AND author_id=?",p.get("case_id"),user))throw invalid("Отправитель и автор обращения не могут подтвердить получение за организацию");
        if(i.get("accepted_by")!=null){if(!user.equals(s(i,"accepted_by")))throw missing();return recipient(s(p,"id"),user);}
        if(db.update("UPDATE exchange_invitations SET accepted_by=? WHERE id=? AND accepted_by IS NULL AND revoked_at IS NULL",user,i.get("id"))!=1)throw conflict();bump(p,Action.INVITATION_ACCEPTED,"Получатель принял доступ к выбранному пакету",null,user,null);return recipient(s(p,"id"),user);}
    private Map<String,Object> recipientAccess(String key,String user,Integer revision){var p=row("exchange_packets",key);current(p);state(p,PacketState.SENT,PacketState.RECEIVED,PacketState.ANSWERED,PacketState.REVIEWED);if(!access.exists("SELECT count(*) FROM exchange_invitations i JOIN users u ON u.id=i.accepted_by WHERE i.packet_id=? AND i.accepted_by=? AND i.revoked_at IS NULL AND datetime(i.expires_at)>datetime('now') AND u.status='ACTIVE'",key,user))throw missing();if(revision!=null){if(rev(p)!=revision)throw conflict();if(access.exists("SELECT count(*) FROM resident_cases WHERE id=? AND status='CLOSED'",p.get("case_id")))throw invalid("Обращение закрыто");}return p;}
    public List<Map<String,Object>> inbox(String user){var result=new ArrayList<Map<String,Object>>();for(var p:db.queryForList("SELECT DISTINCT p.id FROM exchange_packets p JOIN exchange_invitations i ON i.packet_id=p.id WHERE i.accepted_by=? AND i.revoked_at IS NULL AND datetime(i.expires_at)>datetime('now')",user)){try{result.add(recipient(s(p,"id"),user));}catch(BusinessException ignored){/* Revoked house service invalidates old grants. */}}return result;}
    public Map<String,Object> recipient(String key,String user){var p=recipientAccess(key,user,null);var result=new LinkedHashMap<String,Object>();for(String k:List.of("id","subject","statement","disclosure_basis","authority","materials_note","address_snapshot","state","due_at","due_basis","revision"))result.put(k,p.get(k));result.put("files",db.queryForList("SELECT id,title,mime,sha256,size_bytes FROM exchange_packet_files WHERE packet_id=?",key));var replies=db.queryForList("SELECT id,version,state,answer,author_id,review_note,created_at FROM exchange_replies WHERE packet_id=? AND (state<>'DRAFT' OR author_id=?) ORDER BY version",key,user);for(var a:replies)a.put("files",db.queryForList("SELECT id,title,mime,sha256,size_bytes FROM exchange_reply_files WHERE reply_id=?",a.get("id")));result.put("answers",replies);return result;}
    @Transactional public Map<String,Object> acknowledge(String key,ExchangeRequests.RecipientAction r,String user){var p=recipientAccess(key,user,r.revision());state(p,PacketState.SENT);db.update("UPDATE exchange_packets SET state='RECEIVED' WHERE id=?",key);bump(p,Action.PACKET_RECEIVED,r.note(),null,user,"Организация подтвердила получение материалов в кабинете. Ожидаем ответ.");return recipient(key,user);}
    @Transactional public Map<String,Object> reply(String key,ExchangeRequests.Reply r,String user){var p=recipientAccess(key,user,r.revision());state(p,PacketState.RECEIVED);var drafts=db.queryForList("SELECT * FROM exchange_replies WHERE packet_id=? AND state='DRAFT'",key);if(drafts.isEmpty()){int version=db.queryForObject("SELECT coalesce(max(version),0)+1 FROM exchange_replies WHERE packet_id=?",Integer.class,key);db.update("INSERT INTO exchange_replies(id,packet_id,version,state,origin,answer,author_id,created_at) VALUES (?,?,?,'DRAFT','RECIPIENT',?,?,?)",id(),key,version,r.answer(),user,now());}else{if(!user.equals(s(drafts.get(0),"author_id")))throw invalid("Ответ уже готовит другой получатель");db.update("UPDATE exchange_replies SET answer=? WHERE id=?",r.answer(),drafts.get(0).get("id"));}bump(p,Action.REPLY_DRAFTED,"Получатель сохранил черновик ответа",null,user,null);return recipient(key,user);}
    @Transactional public Map<String,Object> upload(String key,int revision,String title,byte[] bytes,String mime,String user){var p=recipientAccess(key,user,revision);state(p,PacketState.RECEIVED);var replies=db.queryForList("SELECT id FROM exchange_replies WHERE packet_id=? AND state='DRAFT' AND author_id=?",key,user);if(replies.isEmpty())throw invalid("Сначала сохраните текст ответа");String reply=s(replies.get(0),"id");if(bytes.length==0||bytes.length>10*1024*1024||!ResidentCaseService.validDocument(bytes,mime))throw invalid("Нужен PDF, JPEG или PNG до 10 МБ");if(db.queryForObject("SELECT count(*) FROM exchange_reply_files WHERE reply_id=?",Integer.class,reply)>=20)throw invalid("В ответе уже 20 файлов");String file=id(),storage="exchange/"+key+"/"+file;store.put(storage,bytes,mime);db.update("INSERT INTO exchange_reply_files(id,reply_id,title,mime,sha256,size_bytes,storage_key,uploaded_at) VALUES (?,?,?,?,?,?,?,?)",file,reply,title,mime,hash(bytes),bytes.length,storage,now());bump(p,Action.REPLY_FILE_ADDED,"Добавлен файл черновика ответа",null,user,null);return recipient(key,user);}
    @Transactional public Map<String,Object> publish(String key,ExchangeRequests.RecipientAction r,String user){var p=recipientAccess(key,user,r.revision());state(p,PacketState.RECEIVED);if(db.update("UPDATE exchange_replies SET state='PUBLISHED',published_at=? WHERE packet_id=? AND state='DRAFT' AND author_id=?",now(),key,user)!=1)throw invalid("Нет вашего черновика ответа");db.update("UPDATE exchange_packets SET state='ANSWERED' WHERE id=?",key);bump(p,Action.REPLY_PUBLISHED,r.note(),null,user,"Организация прислала ответ. Сотрудник проверяет результат; обращение ещё не закрыто.");return recipient(key,user);}
    @Transactional public Workspace manualAnswer(String key,ExchangeRequests.ManualAnswer r,String user){var p=mutate(key,user,r.revision(),r.caseRevision());state(p,PacketState.RECEIVED);manual(p);evidence(r.evidenceVersionId(),s(p,"case_id"));unusedProof(key,r.evidenceVersionId());int version=db.queryForObject("SELECT coalesce(max(version),0)+1 FROM exchange_replies WHERE packet_id=?",Integer.class,key);db.update("INSERT INTO exchange_replies(id,packet_id,version,state,origin,answer,author_id,created_at,published_at) VALUES (?,?,?,'PUBLISHED','MANUAL',?,?,?,?)",id(),key,version,r.answer(),user,now(),now());db.update("UPDATE exchange_packets SET state='ANSWERED' WHERE id=?",key);bump(p,Action.REPLY_PUBLISHED,r.answer(),r.evidenceVersionId(),user,"Получен документ с ответом организации. Сотрудник проверяет результат.");return workspace(s(p,"case_id"),user);}
    @Transactional public Workspace review(String key,ExchangeRequests.Review r,String user){var p=mutate(key,user,r.revision(),r.caseRevision());state(p,PacketState.ANSWERED);String caseId=s(p,"case_id");var answer=db.queryForList("SELECT * FROM exchange_replies WHERE packet_id=? AND state='PUBLISHED' ORDER BY version DESC LIMIT 1",key).get(0);boolean accept=r.decision()==ReviewDecision.ACCEPT;
        if(accept){var files=db.queryForList("SELECT * FROM exchange_reply_files WHERE reply_id=?",answer.get("id"));int total=db.queryForObject("SELECT count(*) FROM case_documents WHERE case_id=?",Integer.class,caseId);long size=db.queryForObject("SELECT coalesce(sum(v.size_bytes),0) FROM case_document_versions v JOIN case_documents d ON d.id=v.document_id WHERE d.case_id=?",Long.class,caseId);if(total+files.size()>20||size+files.stream().mapToLong(f->((Number)f.get("size_bytes")).longValue()).sum()>100L*1024*1024)throw invalid("Лимит документов обращения будет превышен. Верните ответ на уточнение и согласуйте меньший состав приложений");
            for(var f:files){String doc=id(),version=id();db.update("INSERT INTO case_documents(id,case_id,title,created_at) VALUES (?,?,?,?)",doc,caseId,"Ответ организации: "+s(f,"title").substring(0,Math.min(130,s(f,"title").length())),now());db.update("INSERT INTO case_document_versions(id,document_id,version,uploaded_by,storage_key,mime,sha256,size_bytes,created_at) VALUES (?,?,1,?,?,?,?,?,?)",version,doc,user,f.get("storage_key"),f.get("mime"),f.get("sha256"),f.get("size_bytes"),now());db.update("UPDATE exchange_reply_files SET imported_version_id=? WHERE id=?",version,f.get("id"));}}
        db.update("UPDATE exchange_replies SET state=?,review_note=?,resident_summary=?,reviewed_by=?,reviewed_at=? WHERE id=?",accept?"ACCEPTED":"RETURNED",r.note(),r.residentSummary(),user,now(),answer.get("id"));db.update("UPDATE exchange_packets SET state=? WHERE id=?",accept?"REVIEWED":"RECEIVED",key);bump(p,Action.REPLY_REVIEWED,r.note(),null,user,(accept?"Ответ организации рассмотрен: ":"Организации направлено уточнение: ")+r.residentSummary());return workspace(caseId,user);}
    public String print(String key,String user){var p=row("exchange_packets",key);var c=cases.get(s(p,"case_id"),user);if(!sender(c,user))throw missing();current(p);if("DRAFT".equals(s(p,"state")))throw invalid("Сначала зафиксируйте состав пакета");var out=new StringBuilder("<!doctype html><html lang=\"ru\"><meta charset=\"utf-8\"><title>Состав и текст пакета</title><h1>").append(escape(s(p,"subject"))).append("</h1>");out.append("<p>Пакет: ").append(escape(key)).append("</p>");try{var channel=mapper.readTree(s(p,"channel_snapshot"));out.append("<h2>Проверенный получатель</h2><p>").append(escape(channel.path("organization_name").asText())).append("</p><p>Контакт: ").append(escape(channel.path("contact").asText())).append("</p><p>Проверка канала: ").append(escape(channel.path("source_reference").asText())).append("</p>");}catch(java.io.IOException e){throw new IllegalStateException(e);}String[][] labels={{"statement","Текст"},{"disclosure_basis","Основание передачи"},{"authority","Полномочия отправителя"},{"materials_note","Состав материалов"},{"address_snapshot","Адрес, если выбран для передачи"},{"due_at","Срок ответа"},{"due_basis","Основание срока"}};for(var label:labels)out.append("<p><strong>").append(label[1]).append(": </strong>").append(escape(s(p,label[0]))).append("</p>");out.append("<h2>Зафиксированные версии приложений</h2><ul>");for(var f:db.queryForList("SELECT title,mime,sha256,size_bytes FROM exchange_packet_files WHERE packet_id=?",key))out.append("<li>").append(escape(s(f,"title"))).append(" · ").append(escape(s(f,"mime"))).append(" · ").append(escape(s(f,"size_bytes"))).append(" байт · SHA-256 ").append(escape(s(f,"sha256"))).append("</li>");return out.append("</ul><p>Подготовленные материалы. Эта выгрузка не подписана электронной подписью и не подтверждает отправку, получение, выполненные работы или перерасчёт.</p></html>").toString();}
    private static String escape(String value){return value==null?"Не указано":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    public ResidentCaseService.FileData file(String key,String file,boolean reply,String user){var p=row("exchange_packets",key);boolean staff=false;try{staff=sender(cases.get(s(p,"case_id"),user),user);}catch(BusinessException ignored){}if(!staff)recipientAccess(key,user,null);current(p);
        List<Map<String,Object>> rows=reply?db.queryForList("SELECT f.*,a.state,a.author_id FROM exchange_reply_files f JOIN exchange_replies a ON a.id=f.reply_id WHERE f.id=? AND a.packet_id=?",file,key):db.queryForList("SELECT * FROM exchange_packet_files WHERE id=? AND packet_id=?",file,key);if(rows.isEmpty())throw missing();var f=rows.get(0);if(reply&&"DRAFT".equals(s(f,"state"))&&(staff||!user.equals(s(f,"author_id"))))throw missing();return new ResidentCaseService.FileData(store.get(s(f,"storage_key")),s(f,"mime"));}
}
